def main():
    bank_path = ROOT / "data/usmle-module-bank.json"
    bank = json.loads(bank_path.read_text(encoding="utf-8"))
    replacements = {4: finalize(4, MODULE_4), 5: finalize(5, MODULE_5)}
    assert {4, 5}.issubset({m["moduleNumber"] for m in bank["modules"]})
    for module in bank["modules"]:
        if module["moduleNumber"] in replacements:
            module["questions"] = replacements[module["moduleNumber"]]
    assert "TBD" not in json.dumps(replacements), "Unverified source location"
    bank_path.write_text(json.dumps(bank, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")
    print("Wrote 15 questions each to Modules 4 and 5; preserved all other modules.")


if __name__ == "__main__":
    main()
